rec('cuisineunplugged',['Cuisine Unplugged Pullman Bangkok King Power','吃到飽','','週五、週六晚上帝王蟹吃到飽 18:00–22:30。週末價網路上從 ฿2,400 到 ฿2,599 net 都有（餐廳自己的頁面就不一致），平日晚餐約 ฿1,750；線上訂位常有折扣。12/18（五）或 12/19（六）晚上可以排。','https://cuisineunplugged.com/']);
rec('espresso',['Espresso InterContinental Bangkok','吃到飽','','高級海鮮晚餐：加拿大龍蝦、阿拉斯加帝王蟹、法國生蠔。週三、四、日 ฿2,250++，週五、六 ฿2,350++（Eatigo 資料；++ 要再加 10% 服務費和 7% 稅）。在 Ploenchit，逛完 Central 一帶可以接。','https://eatigo.com/en/branches/3370896500610']);
rec('foodexchange',['Food Exchange on 20 Novotel Bangkok Sukhumvit 20','吃到飽','','只有週六晚上的 Crab Paradise：帝王蟹、岩龍蝦、現開生蠔。原價 ฿2,099 net，飯店頁面有 ฿1,399 net 的特價，不含飲料。12/19（六）可以排。','https://www.novotelbangkoksukhumvit20.com/offers/crab-buffet-bangkok/']);
rec('ventisi',['Ventisi Centara Grand at CentralWorld','吃到飽','','週六晚上海鮮吃到飽：泰國河蝦、岩龍蝦、鮭魚現點現做，約 ฿2,490 含無限暢飲（Time Out 資料，價格可能已調整）。','https://www.timeout.com/bangkok/things-to-do/a-saturday-seafood-buffet-in-the-city-centre']);
// 天氣：12/2 前用 Open-Meteo 歷史資料（2015–2025 同一天）；進入 16 天預報範圍後改抓即時預報
const WX={'18':{hi:30.6,lo:22.0,rain:0,wet:0},'19':{hi:30.4,lo:21.3,rain:0,wet:0},'20':{hi:30.7,lo:20.9,rain:9,wet:1},'21':{hi:30.7,lo:21.3,rain:0,wet:0},'22':{hi:31.0,lo:21.6,rain:0,wet:0},'23':{hi:31.2,lo:22.2,rain:0,wet:0}};
const wxOf=date=>{let f=state.wxlive?.d?.[date];return f?{hi:f.hi,lo:f.lo,p:f.p,live:1}:{hi:WX[date].hi,lo:WX[date].lo,p:WX[date].rain,wet:WX[date].wet}};
const wxIcon=p=>p>=50?'rain':p>=20?'cloud':'sun';
function wxCard(date){let w=wxOf(date);return `<div class="wx"><span class="wx-i">${ic(wxIcon(w.p))}</span><div><b>${Math.round(w.hi)}° <span>/ ${Math.round(w.lo)}°</span></b><small>${w.live?`即時預報 · ${esc(state.wxlive.at)} 更新`:`過去 11 年的同一天有 ${w.wet} 天下雨 · 12/2 起換成即時預報`}</small></div><div class="wx-p"><b>${w.p}%</b><small>降雨機率</small></div></div>`}
async function loadWx(){let last=new Date('2026-12-23T23:59:00+07:00'),now=Date.now();if((last-now)/864e5>15||now>last)return;if(state.wxlive&&now-state.wxlive.t<3*3600e3)return;try{let r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=13.75&longitude=100.52&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=Asia%2FBangkok&start_date=2026-12-18&end_date=2026-12-23',{signal:AbortSignal.timeout(8000)});if(!r.ok)return;let j=await r.json(),d={};j.daily.time.forEach((t,i)=>{if(j.daily.temperature_2m_max[i]!=null)d[t.slice(8)]={hi:j.daily.temperature_2m_max[i],lo:j.daily.temperature_2m_min[i],p:j.daily.precipitation_probability_max[i]??0}});if(!Object.keys(d).length)return;state.wxlive={t:now,at:new Date(now).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}),d};save();if(tab==='days')render()}catch{}}
