function applyPalette(){let r=document.documentElement;if(!r?.style)return;let mm=typeof matchMedia==='function'&&matchMedia('(prefers-color-scheme: dark)').matches,dark=r.dataset.theme==='dark'||(r.dataset.theme!=='light'&&mm),p=PAL[state.palette]||PAL.coral,v=p[dark?'d':'l']||{};PTOK.forEach(k=>r.style.removeProperty('--'+k));Object.entries(v).forEach(([k,x])=>r.style.setProperty('--'+k,x));let pop=$('#palpop');if(pop)pop.innerHTML=Object.entries(PAL).map(([k,q])=>`<button data-pal="${k}" class="${(state.palette||'coral')===k?'on':''}"><i style="background:${q.sw}"></i>${q.name}</button>`).join('')}
