function openDriver(id){let th=TH[id],addr=id==='hotel'?'135/6 Phetphraram Yaek 9 Rd., Bangkapi, Huaykhwang, Bangkok 10310':'',mapTh='https://www.google.com/maps/search/?api=1&hl=th&query='+encodeURIComponent(P[id][0]+(id==='hotel'?' 135/6 Phetphraram Yaek 9':''));
$('#driverBody').innerHTML=`<p class="dr-ask">ช่วยไปส่งที่นี่ได้ไหมครับ/คะ<small>請載我們到這裡</small></p>${th?`<div class="dr-th">${esc(th)}</div>`:''}<div class="dr-en">${esc(P[id][0])}</div>${addr?`<div class="dr-addr">${esc(addr)}</div>`:''}<p class="dr-zh">${esc(zh(id))}</p>${th?'':`<p class="dr-note">這個地點我沒有可靠的泰文名稱。司機看不懂的話，按下面開泰文版 Google 地圖給他看。${id==='hotel'?'也可以跟飯店櫃檯要一張泰文名片。':''}</p>`}<div class="actions"><a class="btn primary" href="${mapTh}" target="_blank" rel="noopener">${ic('nav')}Google 地圖（泰文）</a><button class="btn" data-close>關閉</button></div>`;
$('#driver').hidden=false;document.querySelectorAll('#driver [data-close]').forEach(b=>b.onclick=()=>$('#driver').hidden=true)}
// ---------- 換算＋快速記帳 ----------
const CATS=['餐飲','交通','購物','按摩','門票活動','酒水夜生活','其他'];
const catFor=pid=>{let c=P[pid]?.[1];return c==='購物'?'購物':c==='交通'?'交通':c==='按摩'?'按摩':c==='酒吧'?'酒水夜生活':c==='景點'?'門票活動':'餐飲'};
let quick={amt:'',place:'hotel',date:'18',cat:'餐飲',name:''};
function openQuick(o={}){let t=todayInfo(),pl=o.place||t?.next?.e[1]||dayItems(D[day].date).at(-1)?.e[1]||'hotel';quick={amt:'',place:pl,date:o.date||t?.date||D[day].date,cat:o.cat||catFor(pl),name:''};$('#calc').hidden=false;renderQuick()}
function renderQuick(){let v=+quick.amt||0,keys=['1','2','3','4','5','6','7','8','9','.','0','⌫'];
$('#calcBody').innerHTML=`<div class="sheethead"><div><div class="tag">1 THB = ${state.rate} TWD</div><h3 id="calcTitle">換算・記一筆</h3></div><button class="iconbtn btn" data-close aria-label="關閉">${ic('x')}</button></div><div class="calc-disp"><div class="calc-thb">฿${quick.amt?esc(quick.amt):'0'}</div><div class="calc-twd">≈ NT$${num(v*state.rate)}</div></div><div class="keypad">${keys.map(k=>`<button type="button" data-key="${k}">${k}</button>`).join('')}</div><div class="chips">${CATS.map(c=>`<button type="button" data-cat="${c}" class="${quick.cat===c?'on':''}">${c}</button>`).join('')}</div><div class="formrow"><label>地點<select id="qplace">${Object.keys(P).filter(id=>!placeHidden(id)).map(id=>`<option value="${id}" ${id===quick.place?'selected':''}>${esc(zh(id))}</option>`).join('')}</select></label><label>日期<select id="qdate">${D.map(d=>`<option value="${d.date}" ${d.date===quick.date?'selected':''}>12/${d.date}（${d.week}）</option>`).join('')}</select></label></div><label>品項（選填）<input id="qname" maxlength="200" value="${esc(quick.name)}" placeholder="咖哩蟹、車資…"></label><button class="btn primary big" id="qsave" ${v>0?'':'disabled'}>存成一筆 ฿${num(v)}</button>`;
document.querySelectorAll('#calc [data-close]').forEach(b=>b.onclick=closeQuick);
document.querySelectorAll('#calc [data-key]').forEach(b=>b.onclick=()=>{let k=b.dataset.key,a=quick.amt;if(k==='⌫')a=a.slice(0,-1);else if(k==='.'){if(!a.includes('.'))a=(a||'0')+'.'}else if(a.length<9&&!/\.\d\d$/.test(a))a=a==='0'?k:a+k;quick.amt=a;renderQuick()});
document.querySelectorAll('#calc [data-cat]').forEach(b=>b.onclick=()=>{quick.cat=b.dataset.cat;renderQuick()});
$('#qplace').onchange=e=>{quick.place=e.target.value;quick.cat=catFor(quick.place);renderQuick()};$('#qdate').onchange=e=>quick.date=e.target.value;$('#qname').oninput=e=>quick.name=e.target.value;
$('#qsave').onclick=()=>{let thb=+quick.amt;if(!(thb>0))return;let rec={id:crypto.randomUUID(),at:Date.now(),thb,rate:state.rate,place:quick.place,category:quick.cat,date:'2026-12-'+quick.date,name:quick.name.trim().slice(0,200)};state.expenses.push(rec);save();closeQuick();toast(`已記 ฿${num(thb)} ≈ NT$${num(thb*state.rate)}`,()=>{state.expenses=state.expenses.filter(x=>x.id!==rec.id);save();render()})}}
function closeQuick(){$('#calc').hidden=true;render()}
// ---------- 依旅程階段變化的首頁 ----------
const phase=()=>{let d=bkkNow().date;return d<'2026-12-18'?'before':d>'2026-12-23'?'after':'during'};
function phaseStrip(){let ph=phase();if(ph==='before'){let all=PREP.flatMap(g=>g[1]),done=all.filter(x=>state.done['prep:'+x]).length,n=daysTo(FL[0].iso);return `<button class="prestrip" data-goto="bookings"><span>${ic('ticket')}出發前清單 <b>${done} / ${all.length}</b></span><span>${n<=3&&n>0?'記得填泰國入境卡 TDAC':'還有 '+n+' 天'} ›</span></button>`}if(ph==='after'){let ids=D.flatMap(d=>dayItems(d.date)),done=ids.filter(x=>state.done[x.id]).length;return `<div class="recap"><h3>${ic('cake')}旅程完成</h3><div class="recap-grid"><div><b>NT$${num(sum())}</b><small>總花費</small></div><div><b>${done}</b><small>走完的行程</small></div><div><b>${new Set(ids.map(x=>x.e[1])).size}</b><small>去過的地點</small></div></div></div>`}return ''}
// ---------- 下雨提醒 ----------
const INDOOR=['terminal21','iconsiam','emquartier','central','bacc','onebangkok'];
function rainAlert(date){let w=wxOf(date);if(w.p<50)return '';return `<div class="rainalert">${ic('rain')}<div><b>這天降雨機率 ${w.p}%</b><small>午後可能下雨，可以換成室內行程：</small><div class="chips">${INDOOR.map(id=>`<button type="button" data-add="${id}">${esc(zh(id))}</button>`).join('')}</div></div></div>`}
// ---------- 緊急資訊與泰文短句 ----------
