function emergencyCard(){return `<div class="card sos"><h3>${ic('help')}緊急資訊</h3>${SOS.map(([n,t])=>`<div class="sosrow"><span>${n}</span><b>${t}</b><button class="btn iconbtn" data-copy="${t}" aria-label="複製 ${n} 電話">${ic('note')}</button></div>`).join('')}<div class="sosrow"><span>住宿 ROYS Hotel</span><b class="addr">135/6 Phetphraram Yaek 9 Rd., Bangkapi, Huaykhwang, Bangkok 10310</b><button class="btn iconbtn" data-driver="hotel" aria-label="給司機看飯店地址">${ic('car')}</button></div><details><summary>護照遺失怎麼辦</summary><p>1. 先到最近的警察局報案，拿報案證明。2. 帶報案證明、照片和身分證影本到駐泰辦事處，申請補發護照或「入國證明書」回台。3. 打電話給航空公司說明狀況。</p></details><small>電話號碼整理自外交部領事事務局，出發前可再到 boca.gov.tw 核對一次。</small></div>`}
const PHR=[['你好','สวัสดี','sa-wat-dee'],['謝謝','ขอบคุณ','khob-khun'],['多少錢？','เท่าไหร่','tao-rai'],['一公斤多少？','กิโลละเท่าไหร่','kilo la tao-rai'],['可以算便宜一點嗎？','ลดได้ไหม','lot dai mai'],['不要辣','ไม่เผ็ด','mai phet'],['小辣','เผ็ดน้อย','phet noi'],['不要香菜','ไม่ใส่ผักชี','mai sai phak-chee'],['可以幫我煮嗎？','ทำให้ได้ไหม','tham hai dai mai'],['買單','เช็คบิล','check bin'],['去這裡','ไปที่นี่','pai tee-nee'],['廁所在哪？','ห้องน้ำอยู่ที่ไหน','hong-nam yu tee-nai'],['生日快樂','สุขสันต์วันเกิด','suk-san wan-koet']];
const canSay=()=>typeof speechSynthesis!=='undefined';
function say(t){if(!canSay())return;let u=new SpeechSynthesisUtterance(t);u.lang='th-TH';u.rate=.8;speechSynthesis.cancel();speechSynthesis.speak(u)}
function phraseCard(){let m=state.sex!=='f',end=m?'ครับ':'ค่ะ',endR=m?'khrap':'kha';return `<div class="card phr"><div class="phrhead"><h3>${ic('sight')}實用泰文</h3><div class="seg2"><button data-sex="m" class="${m?'on':''}">我是男生</button><button data-sex="f" class="${m?'':'on'}">我是女生</button></div></div><p class="muted">句尾加「${end}（${endR}）」比較有禮貌，已經幫你加好了。${canSay()?'點一下會念出來。':''}</p><div class="phrgrid">${PHR.map(([z,t,r])=>`<button class="phrase" ${canSay()?`data-say="${esc(t+end)}"`:''}><b>${z}</b><span>${t}${end}</span><small>${r} ${endR}</small></button>`).join('')}</div></div>`}
// ---------- 兩支手機同步（Claude 連結上才有） ----------
const SYNC=['done','notes','schedule','overrides','surprise','custom','expenses'];
let syncRef=null,syncLast=null,syncExists=false,pushing=false,pushAgain=false,pushTimer=null,syncState='local';
const syncView=()=>({done:state.done||{},notes:state.notes||{},schedule:state.schedule||{},overrides:state.overrides||{},surprise:state.surprise||{},custom:Object.fromEntries((state.custom||[]).map(c=>[c.id,c])),expenses:Object.fromEntries((state.expenses||[]).map(x=>[x.id,x]))});
const clone=o=>JSON.parse(JSON.stringify(o));
function fromView(v){let m=f=>Object.fromEntries(Object.entries(v[f]||{}).filter(([,x])=>x!==null&&x!==undefined));state.done=m('done');state.notes=m('notes');state.schedule=m('schedule');state.overrides=m('overrides');state.surprise=m('surprise');state.custom=Object.values(m('custom')).filter(c=>P[c.place]);state.expenses=Object.values(m('expenses')).filter(x=>P[x.place]&&x.thb>0).sort((a,b)=>(a.at||0)-(b.at||0))}
function syncDiff(){let cur=syncView(),patch={},any=false;for(const f of SYNC){let a=syncLast?.[f]||{},b=cur[f],p={};for(const k in b)if(JSON.stringify(a[k])!==JSON.stringify(b[k])){p[k]=b[k];any=true}for(const k in a)if(a[k]!=null&&!(k in b)){p[k]=null;any=true}if(Object.keys(p).length)patch[f]=p}return any?patch:null}
function applyPatch(v,patch){for(const f in patch){v[f]={...(v[f]||{})};for(const k in patch[f]){if(patch[f][k]===null)delete v[f][k];else v[f][k]=patch[f][k]}}return v}
function queuePush(){if(!syncRef)return;clearTimeout(pushTimer);pushTimer=setTimeout(push,400)}
async function push(){if(!syncRef)return;if(pushing){pushAgain=true;return}let patch=syncDiff();if(!patch)return;pushing=true;let snap=clone(syncView());try{if(syncExists)await syncRef.update(patch);else{await syncRef.set(snap);syncExists=true}syncLast=snap;setSync('synced')}catch(e){setSync('error')}pushing=false;if(pushAgain){pushAgain=false;push()}}
function setSync(st){syncState=st;let el=$('#syncdot');if(el){el.className='syncdot '+st;el.title=st==='synced'?'兩支手機已同步':st==='error'?'同步失敗，先存在這支手機':st==='wait'?'連線中':'只存在這支手機';el.hidden=st==='local'}}
const busy=()=>!$('#sheet').hidden||!$('#calc').hidden||(document.activeElement&&/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName));
let pendingRender=false;
async function startSync(){let db=null;try{db=await globalThis.claude?.use?.('db')}catch{}if(!db)return;try{syncRef=db.doc('trip/main')}catch{return}setSync('wait');let loaded=false,timer=setTimeout(()=>{if(!loaded)setSync('error')},10000);
syncRef.onSnapshot(sn=>{if(sn.metadata.fromCache&&!sn.exists)return;loaded=true;clearTimeout(timer);if(!sn.exists){syncExists=false;syncLast=null;queuePush();return}syncExists=true;let pend=syncLast?syncDiff():null,v=clone(sn.data());syncLast=clone(v);fromView(pend?applyPatch(v,pend):v);localSave();if(pend)queuePush();else setSync('synced');if(busy())pendingRender=true;else render()},()=>setSync('error'))}
let pop=null,anim=false;
function eventCard(x,d,nextId){if(hidden(x.id,d.date))return `<article class="event" id="event-${x.id}"><div class="time">${x.e[0]}</div><div class="eventbody surprisecard"><span class="bubble c-book">${ic('gift')}</span><div class="tag">驚喜</div><h3>先保密</h3><p>這段行程是驚喜，12/${d.date} 當天就會出現。</p></div></article>`;let {base,e,di,i,id,custom}=x,spent=sum(e[1]),selected=!custom&&hasAlternative(di,i),done=state.done[id],note=state.notes[id];return `<article class="event ${done?'done':''} ${id===nextId?'next':''}" id="event-${id}"><div class="time">${e[0]}</div><div class="eventbody">${bubble(e[1])}<button class="check ${done?'on':''} ${pop===id?'pop':''}" data-done="${id}" aria-label="${done?'取消完成':'標記完成'}">${ic('check')}</button><div class="tag ${e[4]||''}">${id===nextId?'<span class="nextpill">下一站</span>':''}${P[e[1]][1]} · ${custom?'自己排的':selected?'已選替代安排':e[4]==='confirmed'?'已確認':'建議安排'}${state.schedule?.[id]?' · 已調整':''}${!GUEST&&state.surprise?.[id]?' · <span class="surprisetag">驚喜</span>':''}</div><h3>${esc(e[2])}</h3><div class="placeline">${pname(e[1])}</div>${photo(e[1])}${e[3]?`<p>${esc(e[3])}</p>`:''}${selected?`<small>原安排：${esc(base[2])}</small>`:''}${spent?`<small>這裡已記 NT$${num(spent)}</small>`:''}${note?`<div class="notepreview">${ic('note')}<span>${esc(note)}</span></div>`:''}<div class="actions">${nav(e[1])}<button class="btn" data-driver="${e[1]}">${ic('car')}給司機看</button><button class="btn" data-expense="${e[1]}" data-expensedate="${d.date}">${ic('plus')}記一筆</button>${selected?`<button class="btn" data-restore="${id}">還原主行程</button>`:''}<button class="btn iconbtn" data-more="${id}" aria-label="編輯行程、替代選擇與筆記">${ic('more')}</button></div></div></article>`}
function renderDays(){let d=D[day],items=dayItems(d.date).map(x=>x),tdy=todayInfo(),nextId=tdy&&tdy.date===d.date?tdy.next?.id:null,legs=dayLegs(d.date),known=legs.filter(l=>l.known),low=known.reduce((n,l)=>n+l.low,0),high=known.reduce((n,l)=>n+l.high,0);$('#app').innerHTML=`<div class="grid"><section><div class="daybar">${D.map((d,i)=>`<button class="daybtn ${i===day?'active':''}" data-day="${i}"><span>週${d.week}</span><b>12.${d.date}</b><span class="dtemp">${ic(wxIcon(wxOf(d.date).p))}${Math.round(wxOf(d.date).hi)}°</span></button>`).join('')}</div><h2>${d.title}</h2>${phaseStrip()}<p class="sub">${items.map(x=>hidden(x.id,d.date)?'驚喜':zh(x.e[1])).filter((v,i,all)=>i===0||v!==all[i-1]).map(esc).join(' → ')||'今天留白，慢慢玩。'}</p>${tdy&&tdy.date===d.date?nowBar(tdy):''}${wxCard(d.date)}${rainAlert(d.date)}${dayMap(items.filter(x=>!hidden(x.id,d.date)))}<div class="routebanner">${ic('info')}<span>${d.hint}</span></div><details class="transport-summary"><summary><span>${ic('car')}今日交通預留 · 兩人</span><b>฿${num(low)}–${num(high)}</b></summary><small>約 NT$${num(low*state.rate)}–${num(high*state.rate)}${legs.some(l=>!l.known)?'，部分地點待確認':''}。依區域估算，不含高速費和機場附加費，不是即時報價。</small></details>${d.date==='18'?flightCard(FL[0]):''}<div class="timeline">${items.map(x=>legs.filter(l=>l.before===x.id).map(l=>transportCard(l,d.date,hideIds(d.date))).join('')+eventCard(x,d,nextId)).join('')||'<div class="empty">這天還沒有行程，可以把其他天的行程移過來。</div>'}${legs.filter(l=>l.before==='return').map(l=>transportCard(l,d.date)).join('')}</div>${d.date==='23'?'<div style="height:12px"></div>'+flightCard(FL[1]):''}<details class="transport-footnote"><summary>交通怎麼估的</summary><p>依地點所在區域、步行距離和出發時段估一個區間，沒有串即時路況或叫車 App。17–35 泰銖是短程 BTS 單人預留，不是精確票價。台幣用記帳的預設匯率換算，導航交給 Google 地圖查當下路線。</p><a target="_blank" rel="noopener" href="https://suvarnabhumi.airportthai.co.th/service/transportation/detail/211">機場計程車官方費用說明</a></details></section>${side()}</div>`;pop=null;
document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=+b.dataset.day;anim=true;render()});document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>{let id=b.dataset.done;state.done[id]=!state.done[id];pop=state.done[id]?id:null;save();render()});document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{delete state.overrides[b.dataset.restore];state.done[b.dataset.restore]=false;save();render();$('#event-'+b.dataset.restore)?.scrollIntoView({behavior:'smooth',block:'center'});toast('已還原主行程')});document.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{let id=b.dataset.more,c=(state.custom||[]).find(x=>x.id===id);c?openAddSheet(c.place,id):openSheet(id)})}
