document.querySelectorAll('#sheet [data-plan]').forEach(f=>f.onsubmit=ev=>{ev.preventDefault();let fields=f.elements,date=fields.namedItem('date').value,time=fields.namedItem('time').value,title=fields.namedItem('title').value;if(a.locked&&!confirm('這只會改手帳上的顯示，不會改到實際訂位、住宿或班機。'))return;if(updateSchedule(di,i,date,time,title)){day=D.findIndex(d=>d.date===date);closeSheet();$('#event-'+id)?.scrollIntoView({behavior:'smooth',block:'center'});toast('已儲存，並依時間重新排序')}});
