function placeStatus(id){if(D.some(d=>d.events.some(e=>e[1]===id))||(state.custom||[]).some(c=>c.place===id))return '行程中';if(REC.has(id))return '新推薦';return '備案'}
function renderPlaces(){let list=Object.entries(P).filter(([id,p])=>!placeHidden(id)&&!['交通','按摩','住宿'].includes(p[1])&&(filter==='全部'||p[1]===filter||placeStatus(id)===filter)&&(p.join(' ')+' '+zh(id)).toLowerCase().includes(search.toLowerCase()));$('#app').innerHTML=`<div class="eyebrow">PLACES TO GO</div><h2>口袋地點</h2><p class="sub">「行程中」是已排進每日行程的地點，「備案」是替代選擇裡的地點，「新推薦」還沒排進行程。</p><input class="search" id="search" placeholder="搜尋餐廳、市場、Alo…" value="${esc(search)}" aria-label="搜尋地點"><div class="filters">${['全部','行程中','備案','新推薦','吃到飽','餐廳','市場','夜市','購物','景點','酒吧'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><div class="placegrid">${list.map(([id,p])=>`<article class="card">${PH[id]?photo(id):`<div class="place-icon ${CAT[p[1]]||''}">${ic(CATI[p[1]]||'pin')}</div>`}<div class="tag"><span class="st st-${placeStatus(id)}">${placeStatus(id)}</span> ${p[1]}</div><h3>${pname(id)}</h3><p>${p[3]}</p>${sum(id)?`<small>已記 NT$${num(sum(id))}</small>`:''}<div class="actions">${nav(id)}<button class="btn" data-add="${id}">${ic('calendar')}排進行程</button><button class="btn" data-expense="${id}">${ic('plus')}記一筆</button>${p[4]?`<a class="btn" href="${p[4]}" target="_blank" rel="noopener">官網</a>`:''}</div></article>`).join('')||'<div class="empty">找不到符合的地點</div>'}</div>`;$('#search').oninput=e=>{search=e.target.value;let pos=e.target.selectionStart;renderPlaces();bindCommon();$('#search').focus();$('#search').setSelectionRange(pos,pos)};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()})}
const PREP=[['證件',['護照效期還有 6 個月以上','出發前 3 天內線上填泰國數位入境卡 TDAC（免費）','免簽可以停留幾天，出發前查外交部領事局','機票、飯店、Sirimahannop 確認信截圖存在手機']],['錢與網路',['準備泰銖現金：夜市、中國城海鮮、Here Hai 只收現金','信用卡開通海外刷卡','兩支手機的網卡或 eSIM','Grab 或 Bolt 叫車 App 先綁好卡']],['訂位',['Safari 雙園門票＋車行區巴士＋來回接送','12/21 按摩分店與預約時段','決定要不要訂吃到飽（12/18 五、12/19 六晚上）','確認飯店退房與寄放行李服務']],['打包',['寺廟要遮肩膝：薄長褲或長裙','商場冷氣很強：帶一件薄外套','防曬、帽子、太陽眼鏡','慶生小禮物；問 Sirimahannop 能不能帶蛋糕','確認 Alo 想買的款式和尺寸']]];
