function renderBookings(){Object.entries(PREPOLD).forEach(([k,v])=>{if(state.done[k]){state.done['prep:'+v]=true;delete state.done[k]}});$('#app').innerHTML=`<div class="eyebrow">RESERVATIONS</div><h2>訂位票夾</h2><p class="sub">航班、住宿和訂位都收在這裡。</p><div class="bookinggrid"><div class="flightcol">${FL.map(f=>flightCard(f)).join('')}</div>${placeHidden('sirima')?'':`<div class="card reservation"><div class="tag">已確認 · 截圖核對 · 慶生晚餐</div><h3>Sirimahannop</h3><p>2026 / 12 / 22（二）<br><b>18:00 – 20:00 · 兩位</b><br>Reserved for Top Deck</p><p>17:45 報到；15:30 自 ROYS 出發。<br>截圖未載明套餐、訂金、取消條款或靠欄杆席，請查原確認信。</p><div class="actions">${nav('sirima')}<button class="btn" id="ics">加入行事曆 ↓</button><a class="btn" href="https://www.sirimahannop.com/" target="_blank" rel="noopener">餐廳官網</a></div></div>`}<div class="card"><div class="tag confirmed">住宿 · 你已確認</div><h3>ROYS Hotel Bangkok</h3><p>12/18 → 12/23 · 五晚<br>兩人 · 含早餐</p><p>135/6 Phetphraram Yaek 9 Rd., Bangkapi, Huaykhwang, Bangkok 10310</p>${nav('hotel')}</div>${prepCard()}</div>${emergencyCard()}${phraseCard()}${GUEST?'':shareCard()}<div class="card"><h3>資料備份</h3><p class="muted">匯出行程筆記與記帳資料，在另一台裝置匯入即可接續。匯入會取代目前的記錄。</p><div class="actions"><button class="btn" id="export">匯出備份 JSON</button><button class="btn" id="import">匯入備份</button><input type="file" id="importfile" accept="application/json" hidden></div></div>`;document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyText(b.dataset.copy));document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>say(b.dataset.say));document.querySelectorAll('[data-sex]').forEach(b=>b.onclick=()=>{state.sex=b.dataset.sex;localSave();render()});if($('#ics'))$('#ics').onclick=()=>download('Sirimahannop.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Bangkok Slow Trip//ZH\r\nBEGIN:VEVENT\r\nUID:sirimahannop-20261222-bkk@slowtrip\r\nDTSTAMP:20261107T000000Z\r\nDTSTART:20261222T110000Z\r\nDTEND:20261222T130000Z\r\nSUMMARY:Sirimahannop - 2 guests - Top Deck\r\nLOCATION:Asiatique The Riverfront Bangkok\r\nDESCRIPTION:Arrive at 17:45 Bangkok time.\r\nEND:VEVENT\r\nEND:VCALENDAR','text/calendar');document.querySelectorAll('[data-prep]').forEach(x=>x.onchange=()=>{state.done['prep:'+x.dataset.prep]=x.checked;save();render()});$('#export').onclick=()=>download('bangkok-trip-backup.json',JSON.stringify({version:1,state},null,2),'application/json');$('#import').onclick=()=>$('#importfile').click();$('#importfile').onchange=async e=>{try{let b=JSON.parse(await e.target.files[0].text());if(b.version!==1||!b.state||!Array.isArray(b.state.expenses)||!(b.state.rate>0)||!b.state.notes||!b.state.done||!Number.isFinite(b.state.budget)||b.state.expenses.some(x=>!P[x.place]||!Number.isFinite(x.thb)||x.thb<=0||!Number.isFinite(x.rate)||x.rate<=0||!/^2026-12-(18|19|20|21|22|23)$/.test(x.date)||typeof x.id!=='string'||typeof x.name!=='string'))throw Error();if(!confirm('匯入將取代這台裝置的筆記與記帳，確定繼續？'))return;state={schedule:{},overrides:{},...b.state};save();render();toast('備份已匯入')}catch{toast('無法讀取備份，請選擇本 App 匯出的有效 JSON')}}}
function download(name,content,type){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function spendCharts(){if(!state.expenses.length)return `<div class="card chartcard empty-chart">${ic('wallet')}<div><b>每天花多少、花在哪裡</b><small>記下第一筆支出後，這裡會出現每天的花費和各類別的比例。</small></div></div>`;
let byDay=D.map(d=>({k:d.date,label:'12/'+d.date,v:state.expenses.filter(x=>x.date==='2026-12-'+d.date).reduce((a,x)=>a+x.thb*x.rate,0)})),mx=Math.max(...byDay.map(x=>x.v),1),top=byDay.reduce((a,b)=>b.v>a.v?b:a);
let cats={};state.expenses.forEach(x=>cats[x.category]=(cats[x.category]||0)+x.thb*x.rate);let cl=Object.entries(cats).sort((a,b)=>b[1]-a[1]),tot=cl.reduce((a,x)=>a+x[1],0)||1;
return `<div class="chartrow"><div class="card chartcard"><h3>每天花多少</h3><small>台幣，含購物</small><div class="bars" role="img" aria-label="每天花費長條圖">${byDay.map(x=>`<div class="bar" tabindex="0"><span class="tip">${x.label}：NT$${num(x.v)}</span><i style="height:${x.v/mx*100}%"></i>${x===top&&x.v?`<em>${num(x.v)}</em>`:''}<b>${x.label}</b></div>`).join('')}</div></div><div class="card chartcard"><h3>花在哪裡</h3><small>依分類，台幣</small><div class="hbars">${cl.map(([c,v])=>`<div class="hbar"><span>${esc(c)}</span><div><i style="width:${v/cl[0][1]*100}%"></i></div><b>NT$${num(v)}<small> · ${Math.round(v/tot*100)}%</small></b></div>`).join('')}</div></div></div>`}
function renderBudget(){let all=sum(),shopping=state.expenses.filter(x=>x.category==='購物').reduce((a,x)=>a+x.thb*x.rate,0),travel=all-shopping,edit=state.expenses.find(x=>x.id===editExpense),current=edit?.place||expensePlace||'hotel';$('#app').innerHTML=`<div class="eyebrow">TRAVEL EXPENSES</div><h2>旅行記帳</h2><p class="sub">輸入泰銖即時換算台幣；每筆保留入帳匯率，之後改匯率不會改掉舊帳。</p><div class="budgettiles"><div class="card"><small>全程實際支出 · 含購物</small><div class="amount">NT$${num(all)}</div><small>共 ${state.expenses.length} 筆 · 目前兩人合計</small></div><div class="card"><small>旅行支出 · 不含購物</small><div class="amount">NT$${num(travel)}</div><div class="progress"><span style="width:${Math.min(100,travel/state.budget*100)}%"></span></div><small>${travel>state.budget?'已超出預算 NT$'+num(travel-state.budget):'預算剩餘 NT$'+num(state.budget-travel)}</small></div><div class="card"><small>購物獨立統計</small><div class="amount">NT$${num(shopping)}</div><small>Alo、小精品、伴手禮另計</small></div></div>${spendCharts()}<div class="grid"><section><form class="card" id="expenseForm"><h3>${edit?'編輯支出':'＋ 記一筆泰銖支出'}</h3><div class="formrow"><div><label for="amount">金額 THB</label><input id="amount" type="number" min="0.01" step="0.01" required placeholder="例如 1800" value="${edit?.thb||''}"></div><div><label for="expenseRate">這筆匯率：1 THB = TWD</label><input id="expenseRate" type="number" min="0.000001" step="0.000001" required value="${edit?.rate||state.rate}"></div></div><div class="note" id="converted">約 NT$0</div><div class="formrow"><div><label for="place">景點／店家</label><select id="place">${Object.entries(P).map(([id,p])=>`<option value="${id}" ${id===current?'selected':''}>${esc(zh(id))}</option>`).join('')}</select></div><div><label for="category">分類</label><select id="category">${['餐飲','交通','門票活動','按摩','購物','酒水夜生活','其他'].map(x=>`<option ${x===(edit?.category||pendingExpenseCategory||(P[current][1]==='購物'?'購物':P[current][1]==='酒吧'?'酒水夜生活':'餐飲'))?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="formrow"><div><label for="expenseDate">日期</label><select id="expenseDate">${D.map(d=>`<option value="2026-12-${d.date}" ${(edit?.date||expenseDateOverride||'2026-12-'+D[day].date)==='2026-12-'+d.date?'selected':''}>12/${d.date}（${d.week}）</option>`).join('')}</select></div><div><label for="expenseName">品項／備註</label><input id="expenseName" maxlength="200" placeholder="咖哩蟹、Alo 上衣、車資…" value="${esc(edit?.name||'')}"></div></div><button class="btn primary" type="submit">${edit?'儲存修改':'加入記帳'}</button>${edit?'<button class="btn" type="button" id="cancelEdit">取消編輯</button>':''}</form><div class="card"><h3>支出明細</h3><div class="actions"><button class="btn" id="csv">匯出 CSV</button></div>${[...state.expenses].reverse().map(x=>`<div class="expense"><div><b>${esc(x.name||zh(x.place))}</b><br><small>${esc(x.date)} · ${esc(x.category)} · ${esc(zh(x.place))}<br>฿${num(x.thb)} × ${x.rate}</small></div><div style="text-align:right;min-width:100px"><b>NT$${num(x.thb*x.rate)}</b><br><button data-edit="${esc(x.id)}">編輯</button><button data-delete="${esc(x.id)}" aria-label="刪除此筆支出">刪除</button></div></div>`).join('')||'<div class="empty">還沒有支出。從景點的「記一筆」開始。</div>'}</div></section><aside><div class="card"><h3>匯率與預算</h3><label for="rate">預設匯率：1 THB = TWD</label><input id="rate" type="number" min="0.000001" step="0.000001" value="${state.rate}"><small>${esc(state.rateLabel)}</small><div class="actions"><button class="btn" id="saveRate">儲存手動匯率</button><button class="btn" id="refreshRate">更新網路匯率</button></div><p style="font-size:12px" class="muted">網路匯率為參考，非現鈔或信用卡成交價。可輸入換匯總台幣 ÷ 拿到的泰銖。<a href="https://www.exchangerate-api.com" target="_blank" rel="noopener">匯率服務</a> · <a href="https://wise.com/us/currency-converter/thb-to-twd-rate/history" target="_blank" rel="noopener">初始參考</a></p><label for="limit">旅行預算 TWD（不含購物）</label><input id="limit" type="number" min="1" value="${state.budget}"><button class="btn" id="saveLimit">更新預算</button></div><div class="card"><h3>各景點花了多少</h3>${Object.keys(P).filter(id=>sum(id)>0).sort((a,b)=>sum(b)-sum(a)).map(id=>`<div class="expense"><small>${esc(zh(id))}</small><b>NT$${num(sum(id))}</b></div>`).join('')||'<p class="muted">記帳後自動彙整在這裡。</p>'}</div></aside></div>`;
let conv=()=>{$('#converted').textContent='約 NT$'+num((+$('#amount').value||0)*(+$('#expenseRate').value||0))};$('#amount').oninput=conv;$('#expenseRate').oninput=conv;conv();$('#place').onchange=()=>{let cat=P[$('#place').value][1];$('#category').value=cat==='購物'?'購物':cat==='交通'?'交通':cat==='按摩'?'按摩':cat==='酒吧'?'酒水夜生活':cat==='景點'?'門票活動':'餐飲'};
$('#expenseForm').onsubmit=e=>{e.preventDefault();let thb=+$('#amount').value,rate=+$('#expenseRate').value;if(!(thb>0&&rate>0&&Number.isFinite(thb*rate)))return toast('請輸入有效金額與匯率');let record={id:edit?.id||crypto.randomUUID(),at:edit?.at||Date.now(),thb,rate,place:$('#place').value,category:$('#category').value,date:$('#expenseDate').value,name:$('#expenseName').value.trim()};if(edit)state.expenses[state.expenses.findIndex(x=>x.id===edit.id)]=record;else state.expenses.push(record);editExpense=null;expensePlace='';pendingExpenseCategory='';save();render();toast('支出已儲存')};if($('#cancelEdit'))$('#cancelEdit').onclick=()=>{editExpense=null;render()};$('#saveRate').onclick=()=>{let n=+$('#rate').value;if(!(n>0&&Number.isFinite(n)))return toast('請輸入有效匯率');state.rate=n;state.rateLabel='手動匯率 · '+new Date().toLocaleDateString('zh-TW',{timeZone:'Asia/Bangkok'});save();render();toast('新支出將使用此匯率，舊帳保持不變')};$('#refreshRate').onclick=async()=>{let b=$('#refreshRate');b.disabled=true;b.textContent='更新中…';try{let res=await fetch('https://open.er-api.com/v6/latest/THB',{signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error();let d=await res.json();if(d.result!=='success'||!(d.rates?.TWD>0))throw Error();state.rate=d.rates.TWD;state.rateLabel='ExchangeRate-API · '+new Date(d.time_last_update_unix*1000).toLocaleString('zh-TW',{timeZone:'Asia/Bangkok'})+'（曼谷時間）';save();render();toast('已取得參考匯率，舊帳保持不變')}catch{b.disabled=false;b.textContent='更新網路匯率';toast('暫時無法取得匯率，請手動輸入；原匯率未變動')}};$('#saveLimit').onclick=()=>{let n=+$('#limit').value;if(!(n>0&&Number.isFinite(n)))return toast('請輸入有效預算');state.budget=n;save();render()};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{editExpense=b.dataset.edit;render();$('#expenseForm').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{let i=state.expenses.findIndex(x=>x.id===b.dataset.delete),x=state.expenses[i];if(!x)return;state.expenses.splice(i,1);if(editExpense===x.id)editExpense=null;save();render();toast('已刪除這筆支出',()=>{state.expenses.splice(i,0,x);save();render()})});$('#csv').onclick=()=>{let q=s=>'"'+String(s).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';let rows=[['日期','景點','分類','品項','泰銖','匯率 TWD/THB','台幣'],...state.expenses.map(x=>[x.date,P[x.place][0],x.category,x.name,x.thb,x.rate,(x.thb*x.rate).toFixed(2)])];download('bangkok-expenses.csv','\ufeff'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8')};}
